-- Disqualify the Apple M4 overlap-join submissions made before the flush-race
-- fix (wasabipesto/nice#222, commit 7155c49c) on bases 58 and 60, and reset
-- the fields they leave with no qualified search, so the nice-only queue
-- re-issues them.
--
-- Why: on the M4 the race left 2-4e-4 of the must-check candidates out of the
-- list handed to the full check (measured 2026-11-10 against the exact CPU
-- join; with the fix, 0). AMD and NVIDIA runs of the same builds show no loss.
-- Base 57 (1e14 fields) measured clean on the same build and is not touched.
--
-- Scope: the 11,473 submissions listed below and nothing else.
--   base 58: 4,415 submissions on 4,415 fields (build 9a4f7406, v3.4.6)
--   base 60: 7,058 submissions on 6,824 fields (9a4f7406, v3.4.6: 6,483;
--            2709d3f9, v3.4.7-dev: 575)
-- All are username 'mayalaran', search_mode 'niceonly', telemetry route
-- 'join', GPU 'Apple M4 ...'. The list was built twice from the public API
-- (once by GPU model, once by username) with the same result.
--
-- Fields expected to go back to check_level 0: 8,369
-- (base 58: 4,415; base 60: 3,954). The other 2,870 base-60 fields
-- have another qualified submission and stay at check_level 1.
--
-- STEP 3 is needed. `nice_jobs --full` re-evaluates consensus only for
-- fields that have detailed submissions (bases 58 and 60 have none), and
-- nice-only claims select check_level = 0, lowest id first. Without the
-- reset nothing is re-issued. This is the same reset as STEP 2 of the August
-- script, limited to the listed fields.
--
-- Run:   psql -v ON_ERROR_STOP=1 -f disqualify_m4_prefix_join_b58_b60.sql
-- It is one transaction ending in COMMIT; change the last line to ROLLBACK
-- for a dry run. Every statement goes through a primary key or the
-- submissions(field_id, search_mode, disqualified) index; nothing scans a
-- table. Afterwards: `just jobs-full`, so chunk and base totals and the
-- caches follow.

BEGIN;

CREATE TEMP TABLE m4_prefix (
    submission_id BIGINT PRIMARY KEY,
    field_id      BIGINT NOT NULL,
    base_id       INTEGER NOT NULL
) ON COMMIT DROP;


ANALYZE m4_prefix;

------------------------------------------------------------------------
-- STEP 1: checks before anything changes; a mismatch aborts the run
------------------------------------------------------------------------
DO $$
DECLARE
  n BIGINT;
BEGIN
  SELECT count(*) INTO n FROM m4_prefix;
  IF n <> 11473 THEN
    RAISE EXCEPTION 'the list holds % rows, expected 11473', n;
  END IF;

  -- Every listed row is what the header says it is.
  SELECT count(*) INTO n
  FROM m4_prefix m
  JOIN submissions s ON s.id = m.submission_id
  JOIN fields f ON f.id = s.field_id
  WHERE s.field_id = m.field_id
    AND f.base_id = m.base_id
    AND f.base_id IN (58, 60)
    AND s.search_mode = 'niceonly'
    AND s.username = 'mayalaran'
    AND s.telemetry -> 'hardware' ->> 'gpu_model' LIKE 'Apple%'
    AND s.telemetry -> 'pipeline' ->> 'route' = 'join'
    AND s.telemetry ->> 'build_sha' IN (
          '9a4f74063e2d93155132388af39d1e184975e5e2',
          '2709d3f9eff5eba88e406f10d17851f200dae461');
  IF n <> 11473 THEN
    RAISE EXCEPTION 'only % of the 11473 listed submissions match the description', n;
  END IF;

  SELECT count(*) INTO n
  FROM m4_prefix m JOIN submissions s ON s.id = m.submission_id
  WHERE s.disqualified;
  RAISE NOTICE 'listed submissions already disqualified before this run: % (expected 0)', n;
END $$;

------------------------------------------------------------------------
-- STEP 2: disqualify the listed submissions
------------------------------------------------------------------------
UPDATE submissions s
SET disqualified = true
FROM m4_prefix m
WHERE s.id = m.submission_id
  AND s.disqualified = false;
-- expect: UPDATE 11473

------------------------------------------------------------------------
-- STEP 3: listed fields left with no qualified submission go back to
-- check_level 0 (see the header for why the jobs binary does not do this)
------------------------------------------------------------------------
UPDATE fields f
SET check_level = 0
WHERE f.id IN (SELECT field_id FROM m4_prefix)
  AND f.base_id IN (58, 60)
  AND f.check_level = 1
  AND f.canon_submission_id IS NULL
  AND NOT EXISTS (
        SELECT 1 FROM submissions s
        WHERE s.field_id = f.id
          AND s.disqualified = false);
-- expect: UPDATE 8369  (fewer only if a listed field gained a qualified
-- submission after 2026-11-10 01:45 UTC)

------------------------------------------------------------------------
-- STEP 4: verification (read-only)
------------------------------------------------------------------------
-- 4a. The listed fields by base and check level. Expected:
--       58 | 0 | 4415 | 4415000000000000000
--       60 | 0 | 3954 | 39540000000000000000
--       60 | 1 | 2870 | 28700000000000000000
SELECT f.base_id, f.check_level, count(*) AS fields, sum(f.range_size) AS numbers
FROM fields f
WHERE f.id IN (SELECT field_id FROM m4_prefix)
GROUP BY f.base_id, f.check_level
ORDER BY f.base_id, f.check_level;

-- 4b. No listed submission is still qualified. Expected: 0
SELECT count(*) AS still_qualified
FROM m4_prefix m JOIN submissions s ON s.id = m.submission_id
WHERE NOT s.disqualified;

-- 4c. No listed field at check_level 1 rests only on disqualified work.
--     Expected: 0
SELECT count(*) AS cl1_without_qualified_work
FROM fields f
WHERE f.id IN (SELECT field_id FROM m4_prefix)
  AND f.check_level = 1
  AND NOT EXISTS (
        SELECT 1 FROM submissions s
        WHERE s.field_id = f.id AND s.disqualified = false);

COMMIT;
